import{_ as a,o as t,c as i,ag as o}from"./chunks/framework.CxkNbRKf.js";const g=JSON.parse('{"title":"Database migrations (CLI)","description":"","frontmatter":{},"headers":[],"relativePath":"installation-guide/database-migrations-cli.md","filePath":"installation-guide/database-migrations-cli.md","lastUpdated":1786379412000}'),n={name:"installation-guide/database-migrations-cli.md"};function r(s,e,d,l,p,h){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="database-migrations-cli" tabindex="-1">Database migrations (CLI) <a class="header-anchor" href="#database-migrations-cli" aria-label="Permalink to &quot;Database migrations (CLI)&quot;">​</a></h1><p>From NADA <strong>5.5</strong> onward, schema changes ship as timestamped PHP migration files under <code>application/migrations/</code>. The usual upgrade step is:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/nada</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> index.php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cli/migrate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> latest</span></span></code></pre></div><p>The same runner is available in the admin UI at <strong>Settings → Database migration</strong>. For day-to-day upgrades, CLI and UI behave the same; the UI adds clearer output capture and buttons for adjusting the tracked version without re-running SQL. This page documents <strong>CLI commands</strong> and <strong>troubleshooting</strong> when <code>latest</code> fails or the database is already partly upgraded.</p><div class="warning custom-block"><p class="custom-block-title">Back up first</p><p>Migrations change schema and data. Take a full database backup before running or re-running any migration.</p></div><h2 id="before-you-run-migrations" tabindex="-1">Before you run migrations <a class="header-anchor" href="#before-you-run-migrations" aria-label="Permalink to &quot;Before you run migrations&quot;">​</a></h2><ol><li><strong>Working directory</strong> — Run commands from the NADA web root (the folder that contains <code>index.php</code>), not from <code>application/</code> or a parent directory.</li><li><strong>Enable migrations</strong> — In <code>application/config/migration.php</code>, set <code>$config[&#39;migration_enabled&#39;] = TRUE;</code>. The CLI exits with an error if migrations are disabled.</li><li><strong>Database config</strong> — Confirm <code>application/config/database.php</code> points at the correct catalog database.</li><li><strong>After a successful upgrade</strong> — Set <code>$config[&#39;migration_enabled&#39;] = FALSE;</code> again on production systems (same recommendation as the admin UI).</li></ol><h2 id="how-the-version-watermark-works" tabindex="-1">How the version watermark works <a class="header-anchor" href="#how-the-version-watermark-works" aria-label="Permalink to &quot;How the version watermark works&quot;">​</a></h2><p>NADA stores a single version number in the <code>migrations</code> table. That value is a <strong>watermark</strong>: every migration file whose 14-digit timestamp is <strong>less than or equal to</strong> the stored version is treated as <strong>applied</strong>; newer files are <strong>pending</strong>.</p><p>Migration files are named like <code>20260705120001_admin_menu_url_cleanup.php</code> (timestamp + descriptive suffix).</p><p>This is important for troubleshooting: <strong>marking</strong> or <strong>setting</strong> a version only updates the watermark—it does not run SQL. <strong>Unmarking</strong> (lowering the watermark) makes migrations pending again without undoing schema changes.</p><h2 id="cli-command-reference" tabindex="-1">CLI command reference <a class="header-anchor" href="#cli-command-reference" aria-label="Permalink to &quot;CLI command reference&quot;">​</a></h2><p>Run <code>php index.php cli/migrate</code> with no arguments to print built-in help.</p><table tabindex="0"><thead><tr><th>Command</th><th>Purpose</th></tr></thead><tbody><tr><td><code>php index.php cli/migrate current</code></td><td>Show the stored migration version</td></tr><tr><td><code>php index.php cli/migrate list_migrations</code></td><td>List migration files with Pending / Applied / Current</td></tr><tr><td><code>php index.php cli/migrate latest</code></td><td>Apply all pending migrations in order</td></tr><tr><td><code>php index.php cli/migrate version YYYYMMDDHHIISS</code></td><td>Migrate up (or down) to a specific version</td></tr><tr><td><code>php index.php cli/migrate set_version YYYYMMDDHHIISS</code></td><td>Set the watermark <strong>without</strong> running migration code</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Listing migrations</p><p>Use <code>list_migrations</code>, not <code>list</code> — the latter is not a valid CLI command.</p></div><h3 id="equivalent-admin-ui-actions" tabindex="-1">Equivalent admin UI actions <a class="header-anchor" href="#equivalent-admin-ui-actions" aria-label="Permalink to &quot;Equivalent admin UI actions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Goal</th><th>CLI</th><th>Admin UI (<strong>Settings → Database migration</strong>)</th></tr></thead><tbody><tr><td>Apply all pending</td><td><code>cli/migrate latest</code></td><td><strong>Migrate to Latest</strong></td></tr><tr><td>Apply one pending migration</td><td><code>cli/migrate version &lt;ver&gt;</code></td><td><strong>Run</strong> on that row</td></tr><tr><td>Record manual SQL as done</td><td><code>cli/migrate set_version &lt;ver&gt;</code></td><td><strong>Mark as applied</strong> on that row</td></tr><tr><td>Make a migration pending again</td><td><code>cli/migrate set_version &lt;previous_ver&gt;</code></td><td><strong>Unmark</strong> on that row</td></tr></tbody></table><p>For <strong>Mark as applied</strong>, the UI only allows marking versions <strong>newer</strong> than the current watermark. <strong>Unmark</strong> on version <code>V</code> sets the watermark to the migration <strong>immediately before</strong> <code>V</code>, so <code>V</code> and all later migrations become pending again.</p><p>CLI <code>set_version</code> is more general (it sets the watermark to any valid 14-digit version) but has the same effect when you choose the previous migration’s timestamp to unmark.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="latest-fails-with-a-sql-or-php-error" tabindex="-1"><code>latest</code> fails with a SQL or PHP error <a class="header-anchor" href="#latest-fails-with-a-sql-or-php-error" aria-label="Permalink to &quot;`latest` fails with a SQL or PHP error&quot;">​</a></h3><ol><li>Read the full error line printed after <code>Error:</code> (CLI) or the output panel (UI).</li><li>Run <code>php index.php cli/migrate current</code> and <code>php index.php cli/migrate list_migrations</code> to see which migration was last applied.</li><li>Fix the underlying issue (permissions, disk space, incompatible SQL, wrong database, and so on).</li><li>Restore from backup if the failure left the database in an unknown state.</li><li>Re-run <strong><code>php index.php cli/migrate latest</code></strong> (or <code>version &lt;ver&gt;</code> for a single step).</li></ol><p>Migrations run in timestamp order; a failed step usually leaves the watermark at the last <strong>successful</strong> migration. Do not assume a failed migration was recorded as applied unless <code>current</code> shows a higher version.</p><p>Common causes:</p><ul><li><strong>Duplicate column or table</strong> — Changes were already applied manually or from an older upgrade guide while the watermark was still low. See <a href="#migration-partially-applied-already">Migration partially applied already</a> below.</li><li><strong>Migrations disabled</strong> — Enable in <code>application/config/migration.php</code>.</li><li><strong>Wrong database</strong> — CLI uses the same <code>database.php</code> as the site.</li><li><strong>Debug output on production</strong> — <code>db_debug</code> is turned off for the migration session; permanent setting should be <code>$db[&#39;default&#39;][&#39;db_debug&#39;] = FALSE;</code> in <code>database.php</code>.</li></ul><h3 id="migration-partially-applied-already" tabindex="-1">Migration partially applied already <a class="header-anchor" href="#migration-partially-applied-already" aria-label="Permalink to &quot;Migration partially applied already&quot;">​</a></h3><p>Typical after running SQL from an upgrade document by hand, or after a failed retry.</p><ol><li><p>Compare the error (for example “Duplicate column name”) with your schema.</p></li><li><p>If the schema <strong>already matches</strong> what that migration would do, advance the watermark without re-running it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> index.php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cli/migrate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set_version</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> YYYYMMDDHHIISS</span></span></code></pre></div><p>Use the version of the migration you want to treat as applied (usually the one that failed).</p></li><li><p>Run <code>php index.php cli/migrate latest</code> again for any remaining pending migrations.</p></li></ol><p>Only use <code>set_version</code> when you are sure the database already contains that migration’s changes.</p><h3 id="need-to-re-run-a-migration-marked-as-applied" tabindex="-1">Need to re-run a migration marked as applied <a class="header-anchor" href="#need-to-re-run-a-migration-marked-as-applied" aria-label="Permalink to &quot;Need to re-run a migration marked as applied&quot;">​</a></h3><p>Migrations are not guaranteed to be safe to run twice. Re-running can fail with duplicate-object errors or, for data migrations, duplicate or inconsistent data.</p><p>If you must retry:</p><ol><li><p>Back up the database.</p></li><li><p>Lower the watermark to the migration <strong>before</strong> the one you need to re-run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> index.php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cli/migrate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set_version</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PREVIOUS_14_DIGIT_VERSION</span></span></code></pre></div><p>Example: to re-run <code>20260705120001</code>, set the version to the timestamp of the prior file in <code>list_migrations</code>.</p></li><li><p>Run <code>php index.php cli/migrate latest</code> or <code>version</code> for that target only.</p></li></ol><p>Prefer fixing schema manually and <strong>marking as applied</strong> when the migration is not idempotent.</p><h3 id="migrations-table-missing-or-empty" tabindex="-1"><code>migrations</code> table missing or empty <a class="header-anchor" href="#migrations-table-missing-or-empty" aria-label="Permalink to &quot;`migrations` table missing or empty&quot;">​</a></h3><p>The CLI creates the <code>migrations</code> table and initializes version <code>0</code> when you run <code>latest</code> or <code>version</code>. You can also inspect it directly:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> migrations;</span></span></code></pre></div><p>There should normally be one row. If multiple rows exist, NADA uses the <strong>highest</strong> <code>version</code> value as the current watermark.</p><h3 id="cli-shows-html-instead-of-text" tabindex="-1">CLI shows HTML instead of text <a class="header-anchor" href="#cli-shows-html-instead-of-text" aria-label="Permalink to &quot;CLI shows HTML instead of text&quot;">​</a></h3><p>Usually means the request did not hit the CLI controller (wrong path, web-only bootstrap, or invalid method name). Confirm:</p><ul><li>You are in the NADA root with <code>index.php</code>.</li><li>The command uses <code>cli/migrate/...</code> as documented above.</li><li>PHP is invoked from the shell, not via a browser URL.</li></ul><h3 id="when-to-use-the-admin-ui-instead" tabindex="-1">When to use the admin UI instead <a class="header-anchor" href="#when-to-use-the-admin-ui-instead" aria-label="Permalink to &quot;When to use the admin UI instead&quot;">​</a></h3><p>Use <strong>Settings → Database migration</strong> when you want captured migration output on screen, or when you prefer <strong>Mark as applied</strong> / <strong>Unmark</strong> with confirmations. Use CLI for automation, SSH-only servers, and deployment scripts.</p><h2 id="related-documentation" tabindex="-1">Related documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to &quot;Related documentation&quot;">​</a></h2><ul><li><a href="/nada-documentation/admin-guide/web-ui/database-migration.html">Database migration (admin UI)</a> — Running and marking migrations in the browser</li><li><a href="/nada-documentation/installation-guide/upgrade/">Upgrade overview</a> — Version-specific upgrade steps</li></ul>',45)])])}const m=a(n,[["render",r]]);export{g as __pageData,m as default};
